(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-007":{scenario:{company:"Orbitra Commerce Cloud",supervisor:{name:"Lạc Minh Triết",role:{vi:"Trưởng nhóm Bảo mật Ứng dụng",en:"Application Security Lead"}},ref_code:"PT-2611",title:{vi:"Chấm đúng mức độ. Báo cáo trung thực. Không giấu lỗ hổng.",en:"Score it right. Report it honestly. Hide no vulnerability."},brief:{vi:"Đợt kiểm thử bảo mật có ủy quyền PT-2611 trên cổng khách hàng phát hiện tham số id của API /api/orders bị ghép trực tiếp vào câu SQL. Bằng chứng: chỉ tái hiện được khi đã đăng nhập bằng tài khoản khách hàng thường, qua Internet, không cần người khác thao tác; đọc và sửa được dữ liệu đơn hàng, không ảnh hưởng tính sẵn sàng. Đối chiếu phiếu chấm điểm nháp với chuẩn CVSS v3.1 đã duyệt, sửa chỉ số PR và điểm cơ sở, rồi lập báo cáo có căn cứ.",en:"Authorized security test PT-2611 on the customer portal found that the id parameter of the /api/orders API is concatenated directly into a SQL query. Evidence: it reproduces only with a logged-in regular customer account, over the Internet, with no action by another user; order data can be read and modified, availability is not affected. Compare the draft scoring sheet with the approved CVSS v3.1 standard, correct the PR metric and the base score, then write an evidence-based report."},reference_title:{vi:"Chuẩn chấm điểm CVSS v3.1 đã duyệt · PT-2611",en:"Approved CVSS v3.1 scoring standard · PT-2611"},fields:[{id:"PR_METRIC",label:{vi:"Chỉ số PR (quyền cần có)",en:"PR metric (privileges required)"},initial:"PR:N",expected:"PR:L",choices:["PR:N","PR:L","PR:H"],reference:"Nhật ký tái hiện lỗ hổng",ref_value:{vi:"API trả 401 khi không có phiên; tái hiện bằng tài khoản vai trò customer, không cần quyền quản trị",en:"The API returns 401 without a session; reproduced with a customer-role account, no admin rights needed"},hint:{vi:"PR mô tả quyền kẻ tấn công phải có trước khi khai thác; xem API phản hồi thế nào khi không đăng nhập.",en:"PR describes the privileges an attacker needs before exploiting; check how the API responds without a login."}},{id:"CVSS_BASE",label:{vi:"Điểm cơ sở CVSS v3.1",en:"CVSS v3.1 base score"},initial:"9.1",expected:"8.1",reference:"Bảng tính điểm CVSS",ref_value:{vi:"AV:N AC:L UI:N S:U C:H I:H A:N; trọng số PR: N 0.85, L 0.62, H 0.27",en:"AV:N AC:L UI:N S:U C:H I:H A:N; PR weights: N 0.85, L 0.62, H 0.27"},hint:{vi:"Giữ nguyên các chỉ số khác, chỉ thay đúng trọng số PR vào công thức Exploitability.",en:"Keep the other metrics, only put the correct PR weight into the Exploitability formula."}}],sop32:{vi:"CVSS v3.1 khi S:U: ISS = 1 - (1-C)(1-I)(1-A) với mức cao 0.56, không 0; Impact = 6.42 x ISS; Exploitability = 8.22 x AV 0.85 x AC 0.77 x PR x UI 0.85; điểm cơ sở = làm tròn lên 1 chữ số thập phân của Impact + Exploitability.",en:"CVSS v3.1 with S:U: ISS = 1 - (1-C)(1-I)(1-A) with High 0.56, None 0; Impact = 6.42 x ISS; Exploitability = 8.22 x AV 0.85 x AC 0.77 x PR x UI 0.85; base score = Impact + Exploitability rounded up to 1 decimal."},context:{label:"VULN TRACKER / PT-2611",metrics:[{label:{vi:"Thành phần",en:"Component"},value:"/api/orders"},{label:{vi:"Phiên tái hiện",en:"Reproduced with"},value:"customer session"},{label:{vi:"Điểm trên phiếu nháp",en:"Draft score"},value:"9.1 Critical"}]},crisis:{vi:"Giám đốc sản phẩm nhắn: “Ghi mức Medium và dời sang quý sau đi, đừng đưa lỗi này vào báo cáo gửi khách hàng tuần này. Thứ Sáu ra mắt tính năng mới rồi, không được để chậm.”",en:"The product director messages you: “Mark it Medium and push it to next quarter, and keep it out of this week's client report. We launch the new feature on Friday and cannot slip.”"},options:{safe:{vi:"Giữ mức độ theo bằng chứng, báo cáo đầy đủ và báo CISO cùng chủ hệ thống theo SLA; đề xuất vá bằng truy vấn tham số hóa, tạm thời dùng luật WAF và giám sát; chấp nhận rủi ro chỉ khi có phê duyệt bằng văn bản.",en:"Keep the evidence-based severity, report it in full and notify the CISO and system owner per SLA; propose a parameterized query fix with interim WAF rules and monitoring; accept risk only with written approval."},shortcut:{vi:"Hạ xuống Medium và bỏ lỗi khỏi báo cáo khách hàng để kịp ra mắt thứ Sáu.",en:"Downgrade to Medium and drop it from the client report to make the Friday launch."},wait:{vi:"Để phiếu ở trạng thái nháp, chờ sau ngày ra mắt rồi tính tiếp.",en:"Leave the ticket in draft and revisit after the launch."}},questions:{vi:["Bằng chứng nào quyết định chỉ số PR, và bạn tính lại điểm cơ sở CVSS từng bước như thế nào?","Bạn xử lý đề nghị hạ mức và giấu lỗi khỏi báo cáo ra sao mà vẫn giúp được kế hoạch ra mắt một cách an toàn?"],en:["Which evidence decides the PR metric, and how did you recompute the CVSS base score step by step?","How do you handle the request to downgrade and hide the finding while still supporting a safe launch plan?"]},hints:{vi:["Đọc lại nhật ký tái hiện: kẻ tấn công cần quyền gì trước khi gửi được yêu cầu độc hại?","Theo SOP mục 3.2, tính ISS, Impact và Exploitability riêng rồi mới làm tròn lên.","Đọc lại SOP mục 4.2: mức độ dựa trên bằng chứng; chấp nhận rủi ro phải được người có thẩm quyền phê duyệt bằng văn bản."],en:["Re-read the reproduction log: what privileges does an attacker need before sending a malicious request?","Per SOP 3.2, compute ISS, Impact and Exploitability separately before rounding up.","Re-read SOP 4.2: severity follows evidence; risk acceptance needs written approval from an authorized owner."]},terminal:{system:"vuln-triage",settable:["PR_METRIC","CVSS_BASE"],commands:[{cmd:"status",out:{vi:"Phiếu SEC-3318 (nháp): PR:N, điểm 9.1 Critical, chưa gửi; chờ người kiểm thử chính xác nhận",en:"Ticket SEC-3318 (draft): PR:N, score 9.1 Critical, not sent; awaiting lead tester sign-off"}},{cmd:"cat finding.md",out:{vi:"Tham số id của /api/orders ghép chuỗi vào câu SQL; không có phiên đăng nhập thì API trả 401",en:"The id parameter of /api/orders is concatenated into SQL; without a login session the API returns 401"}},{cmd:"cat access.log",out:{vi:"Mọi yêu cầu tái hiện đều mang phiên hợp lệ của tài khoản kiểm thử cust-test-07, vai trò customer",en:"Every reproduction request carries a valid session of test account cust-test-07, role customer"}},{cmd:"cat impact.txt",out:{vi:"Đọc và sửa được đơn hàng (C:H, I:H); dịch vụ không gián đoạn (A:N); không vượt ra ngoài thành phần (S:U)",en:"Orders can be read and modified (C:H, I:H); no service disruption (A:N); stays within the component (S:U)"}},{cmd:"cat policy.txt",out:{vi:"SLA khắc phục: Critical 7 ngày, High 30 ngày, Medium 90 ngày; hạ mức hoặc chấp nhận rủi ro cần CISO duyệt bằng văn bản",en:"Fix SLA: Critical 7 days, High 30 days, Medium 90 days; downgrades or risk acceptance need written CISO approval"}}]}},learning:{summary:{vi:"Kỹ sư bảo mật ứng dụng và kiểm thử xâm nhập đánh giá ứng dụng web, di động và API trong phạm vi được ủy quyền bằng văn bản, tìm lỗ hổng trước kẻ xấu, chấm mức độ theo CVSS, viết báo cáo có bằng chứng và đồng hành cùng đội phát triển khắc phục tận gốc. Giá trị cốt lõi là giảm rủi ro thật cho doanh nghiệp và người dùng; nền tảng bắt buộc là đạo đức nghề nghiệp, tuân thủ quy tắc tham gia và hiểu sâu kiến trúc phần mềm.",en:"Application security and penetration testing engineers assess web, mobile and API applications within a written authorization scope, find vulnerabilities before attackers do, rate severity with CVSS, write evidence-based reports and work with developers on root-cause fixes. The core value is real risk reduction for the business and its users; professional ethics, strict rules of engagement and a deep understanding of software architecture are mandatory foundations."},responsibilities:{vi:["Xác định phạm vi, quy tắc tham gia và giấy ủy quyền trước mỗi đợt kiểm thử.","Mô hình hóa mối đe dọa và rà soát thiết kế bảo mật cho tính năng mới.","Kiểm thử ứng dụng web, API, di động theo OWASP WSTG/MASTG, kết hợp rà soát mã nguồn và công cụ SAST/DAST.","Chấm điểm CVSS, viết báo cáo phát hiện có bằng chứng tái hiện và khuyến nghị khắc phục.","Kiểm tra lại sau khắc phục, đào tạo lập trình viên viết mã an toàn và theo dõi SLA lỗ hổng."],en:["Define scope, rules of engagement and written authorization before every test.","Run threat modeling and security design reviews for new features.","Test web, API and mobile apps following OWASP WSTG/MASTG, combined with code review and SAST/DAST tools.","Score findings with CVSS and write reports with reproduction evidence and remediation advice.","Retest after fixes, train developers in secure coding and track vulnerability SLAs."]},competencies:[{name:{vi:"Hiểu kiến trúc và giao thức",en:"Architecture and protocol fluency"},desc:{vi:"Nắm HTTP, xác thực, phân quyền, cơ sở dữ liệu và luồng dữ liệu của ứng dụng hiện đại.",en:"Understands HTTP, authentication, authorization, databases and data flows of modern applications."}},{name:{vi:"Phương pháp kiểm thử có hệ thống",en:"Systematic testing method"},desc:{vi:"Lập kế hoạch theo rủi ro, bao phủ đủ hạng mục và ghi nhận bằng chứng có thể tái hiện.",en:"Plans by risk, covers every category and records reproducible evidence."}},{name:{vi:"Đánh giá rủi ro và chấm điểm",en:"Risk rating and scoring"},desc:{vi:"Chấm CVSS khách quan theo bằng chứng, giải thích được tác động nghiệp vụ.",en:"Scores CVSS objectively from evidence and explains business impact."}},{name:{vi:"Viết báo cáo và truyền đạt",en:"Reporting and communication"},desc:{vi:"Viết báo cáo rõ cho cả lãnh đạo và lập trình viên, đề xuất cách sửa khả thi.",en:"Writes clear reports for executives and developers with practical fixes."}},{name:{vi:"Đạo đức và tuân thủ",en:"Ethics and compliance"},desc:{vi:"Chỉ kiểm thử khi có ủy quyền, bảo mật dữ liệu thu được và công bố lỗ hổng có trách nhiệm.",en:"Tests only with authorization, protects collected data and discloses responsibly."}}],knowledge:{vi:["OWASP Top 10 (phiên bản hiện hành) và OWASP ASVS làm chuẩn yêu cầu kiểm chứng bảo mật ứng dụng.","OWASP WSTG cho kiểm thử web và OWASP MASTG cho kiểm thử ứng dụng di động.","CVSS v3.1 và v4.0 do FIRST công bố: nhóm chỉ số cơ sở, thời gian và môi trường.","Vòng đời phát triển phần mềm an toàn (Secure SDLC) và mô hình hóa mối đe dọa STRIDE.","ISO/IEC 27001 về kiểm soát an toàn trong phát triển và quy định hiện hành về an toàn thông tin mạng, bảo vệ dữ liệu cá nhân.","Quy trình công bố lỗ hổng có phối hợp (coordinated vulnerability disclosure)."],en:["OWASP Top 10 (current edition) and OWASP ASVS as the application security verification standard.","OWASP WSTG for web testing and OWASP MASTG for mobile application testing.","CVSS v3.1 and v4.0 published by FIRST: base, temporal/threat and environmental metric groups.","Secure software development life cycle (Secure SDLC) and STRIDE threat modeling.","ISO/IEC 27001 controls for secure development and current regulations on network information security and personal data protection.","Coordinated vulnerability disclosure process."]},tools:["Burp Suite Professional","OWASP ZAP","Semgrep / SonarQube (SAST)","Nmap","Postman","Jira (vulnerability tracking)"],tools_en:["Burp Suite Professional","OWASP ZAP","Semgrep / SonarQube (SAST)","Nmap","Postman","Jira (vulnerability tracking)"],kpis:{vi:["Tỷ lệ phát hiện được xác nhận đúng (true positive) trên tổng phát hiện đã báo cáo.","Thời gian trung bình khắc phục lỗ hổng High/Critical so với SLA.","Tỷ lệ lỗ hổng tái xuất hiện sau khi đã đóng.","Độ bao phủ kiểm thử bảo mật trên các ứng dụng trọng yếu mỗi quý."],en:["Share of confirmed true positives among reported findings.","Mean time to remediate High/Critical vulnerabilities against SLA.","Rate of vulnerabilities reappearing after closure.","Security testing coverage of critical applications per quarter."]},day:[{time:"08:30",vi:"Họp đứng với đội phát triển, rà các phiếu lỗ hổng sắp đến hạn SLA.",en:"Stand-up with developers, review vulnerability tickets nearing their SLA."},{time:"09:30",vi:"Xác nhận phạm vi, giấy ủy quyền và môi trường cho đợt kiểm thử API mới.",en:"Confirm scope, authorization and environment for a new API test."},{time:"11:00",vi:"Kiểm thử chức năng xác thực và phân quyền trên môi trường staging.",en:"Test authentication and authorization features on staging."},{time:"14:00",vi:"Rà soát mã nguồn các pull request có thay đổi về xác thực và truy vấn dữ liệu.",en:"Review pull requests that change authentication or data queries."},{time:"16:00",vi:"Viết báo cáo phát hiện, chấm CVSS và họp với chủ sản phẩm về kế hoạch khắc phục.",en:"Write findings, score CVSS and meet the product owner on the fix plan."}],mistakes:{vi:["Kiểm thử ngoài phạm vi hoặc khi chưa có ủy quyền bằng văn bản.","Chấm CVSS theo cảm tính hoặc theo áp lực tiến độ thay vì bằng chứng.","Báo cáo thiếu bước tái hiện và khuyến nghị cụ thể, khiến đội phát triển không sửa được tận gốc."],en:["Testing out of scope or without written authorization.","Scoring CVSS by gut feeling or schedule pressure instead of evidence.","Reports without reproduction steps or concrete advice, so developers cannot fix the root cause."]},career:[{vi:"Chuyên viên kiểm thử bảo mật",en:"Security Tester"},{vi:"Kỹ sư bảo mật ứng dụng",en:"Application Security Engineer"},{vi:"Trưởng nhóm AppSec / Red Team",en:"AppSec / Red Team Lead"},{vi:"Giám đốc bảo mật sản phẩm / CISO",en:"Head of Product Security / CISO"}],glossary:[{term:"CVSS",vi:"Hệ thống chấm điểm mức độ nghiêm trọng lỗ hổng từ 0 đến 10 do FIRST quản lý.",en:"Common Vulnerability Scoring System, a 0 to 10 severity scale maintained by FIRST."},{term:"Rules of Engagement",vi:"Văn bản quy định phạm vi, thời gian, kỹ thuật được phép và đầu mối liên lạc của đợt kiểm thử.",en:"Document defining the scope, timing, allowed techniques and contacts of a test."},{term:"SAST / DAST",vi:"Phân tích bảo mật tĩnh trên mã nguồn và động trên ứng dụng đang chạy.",en:"Static security analysis of source code and dynamic analysis of a running application."},{term:"Threat modeling",vi:"Phân tích có hệ thống các mối đe dọa đối với một thiết kế để chọn biện pháp kiểm soát.",en:"Systematic analysis of threats to a design to choose controls."},{term:"Parameterized query",vi:"Truy vấn tách dữ liệu khỏi câu lệnh SQL, là cách khắc phục gốc lỗi SQL injection.",en:"Query that separates data from the SQL statement, the root fix for SQL injection."}],quiz:[{q:{vi:"Theo CVSS v3.1, điểm cơ sở 8.1 thuộc mức nghiêm trọng nào?",en:"Under CVSS v3.1, which severity rating does a base score of 8.1 fall into?"},options:{vi:["Medium","Critical","High","Low"],en:["Medium","Critical","High","Low"]},answer:2,explain:{vi:"Thang định tính CVSS v3.1: High từ 7.0 đến 8.9, Critical từ 9.0 đến 10.0.",en:"CVSS v3.1 qualitative scale: High is 7.0 to 8.9, Critical is 9.0 to 10.0."}},{q:{vi:"Khách hàng nhờ bạn kiểm thử thêm một máy chủ không có trong giấy ủy quyền “cho tiện”. Bạn làm gì?",en:"The client asks you to test an extra server that is not in the authorization “while you are at it”. What do you do?"},options:{vi:["Chỉ kiểm thử khi phạm vi được cập nhật bằng văn bản và người có thẩm quyền ký","Kiểm thử luôn vì khách hàng đã đồng ý bằng lời","Kiểm thử nhẹ nhàng rồi không ghi vào báo cáo","Nhờ đồng nghiệp kiểm thử thay"],en:["Test only after the scope is updated in writing and signed by an authorized person","Test it now because the client agreed verbally","Test lightly and leave it out of the report","Ask a colleague to test it instead"]},answer:0,explain:{vi:"Kiểm thử ngoài phạm vi ủy quyền có thể vi phạm pháp luật và hợp đồng; phạm vi phải được cập nhật bằng văn bản.",en:"Testing outside the authorized scope can breach law and contract; the scope must be updated in writing."}},{q:{vi:"Chỉ số PR (Privileges Required) trong CVSS mô tả điều gì?",en:"What does the PR (Privileges Required) metric in CVSS describe?"},options:{vi:["Quyền của nạn nhân bị ảnh hưởng","Mức tác động lên dữ liệu","Thời gian cần để vá lỗi","Quyền kẻ tấn công phải có trước khi khai thác"],en:["Privileges of the affected victim","Impact on data","Time needed to patch","Privileges an attacker must hold before exploiting"]},answer:3,explain:{vi:"PR đo mức quyền kẻ tấn công cần có trước khi khai thác: None, Low hoặc High.",en:"PR measures the privileges an attacker needs before exploiting: None, Low or High."}},{q:{vi:"Cách khắc phục tận gốc cho lỗi SQL injection là gì?",en:"What is the root-cause fix for SQL injection?"},options:{vi:["Chỉ chặn bằng WAF","Dùng truy vấn tham số hóa và kiểm tra đầu vào theo danh sách cho phép","Ẩn thông báo lỗi khỏi người dùng","Đổi tên bảng trong cơ sở dữ liệu"],en:["Block it with a WAF only","Use parameterized queries with allow-list input validation","Hide error messages from users","Rename the database tables"]},answer:1,explain:{vi:"WAF chỉ là biện pháp tạm; truy vấn tham số hóa tách dữ liệu khỏi câu lệnh nên loại bỏ nguyên nhân gốc.",en:"A WAF is only interim; parameterized queries separate data from the statement and remove the root cause."}}]}}})})(window.KKR);
